const chatInput = items[0].json.chatInput || "";
const sessionId = items[0].json.sessionId || ""; // sessionId ကိုပါ လက်ခံမယ်
const burmeseRegex = /[\u1000-\u109F]/;
let language = burmeseRegex.test(chatInput) ? "my" : "en";

return {
    language: language,
    chatInput: chatInput,
    sessionId: sessionId // sessionId ကိုပါ ပြန်ထုတ်ပေးမယ်
};

